#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "floyd-warshall.h"


/* Array initialization. */
static
void init_array (int n,
		 DATA_TYPE POLYBENCH_2D(path,N,N,n,n))
{
  int i, j;

  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
      path[i][j] = i*j%7+1;
      if ((i+j)%13 == 0 || (i+j)%7==0 || (i+j)%11 == 0)
         path[i][j] = 999;
    }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_2D(path,N,N,n,n))

{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("path");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
      if ((i * n + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
      fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, path[i][j]);
    }
  POLYBENCH_DUMP_END("path");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_floyd_warshall [[gnu::flatten, gnu::noinline]] (int n,
			   DATA_TYPE POLYBENCH_2D(path,N,N,n,n))
{
  /* Use PolyBench's possibly padded problem size. */
  const int nPB = _PB_N;

  /*
   * Optimized Floyd–Warshall kernel.
   *
   * Transformations:
   *  - Use row pointers (row_k, row_i) to avoid repeated 2D index
   *    arithmetic in the innermost loop.
   *  - For every (k, i), split the j-loop into three regions:
   *        j in [0, k)   : uses the original path[i][k]
   *        j == k        : performs the unique update to path[i][k]
   *        j in (k, nPB) : uses the (possibly) updated path[i][k]
   *
   *    This exactly preserves the original update order (k, i, j)
   *    for all elements, including the subtle dependency through
   *    path[i][k].  Within each region, path[i][k] is provably
   *    invariant, so it can be held in a scalar (pik), improving
   *    cache usage and giving the compiler a better chance to
   *    vectorize the j-loops.
   *
   *  - Accesses within each inner loop are over contiguous elements
   *    of a row, which is friendly to the cache and to SIMD.
   */
#pragma scop
  for (int k = 0; k < nPB; ++k)
  {
    DATA_TYPE* row_k = path[k];

    for (int i = 0; i < nPB; ++i)
    {
      DATA_TYPE* row_i = path[i];

      /* Value of path[i][k] before the j == k update. */
      DATA_TYPE pik = row_i[k];

      /* --- Columns j = 0 .. k-1 (use original pik) --- */
#pragma GCC ivdep
      for (int j = 0; j < k; ++j)
      {
        DATA_TYPE direct = row_i[j];
        DATA_TYPE via_k  = pik + row_k[j];

        if (via_k < direct)
          row_i[j] = via_k;
      }

      /* --- Column j == k: this is the only place where path[i][k] can change. --- */
      {
        DATA_TYPE via_k = pik + row_k[k];

        if (via_k < pik)
        {
          pik      = via_k;  /* new value of path[i][k] */
          row_i[k] = via_k;
        }
      }

      /* --- Columns j = k+1 .. nPB-1 (use possibly updated pik) --- */
#pragma GCC ivdep
      for (int j = k + 1; j < nPB; ++j)
      {
        DATA_TYPE direct = row_i[j];
        DATA_TYPE via_k  = pik + row_k[j];

        if (via_k < direct)
          row_i[j] = via_k;
      }
    }
  }
#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(path, DATA_TYPE, N, N, n, n);


  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(path));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_floyd_warshall (n, POLYBENCH_ARRAY(path));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(path)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(path);

  return 0;
}
