/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_floyd_warshall(int n,
			   DATA_TYPE POLYBENCH_2D(path,N,N,n,n))
{
  /* Use a local restrict-qualified pointer for better alias analysis and
     to encourage the compiler to keep frequently used rows in registers. */
  DATA_TYPE (*restrict p)[n] = path;

  int i, j, k;

#pragma scop
  for (k = 0; k < _PB_N; k++)
    {
      /* Pointer to the k-th row, reused for all i in this k-iteration. */
      DATA_TYPE *restrict pk = p[k];

      for (i = 0; i < _PB_N; i++)
        {
          DATA_TYPE *restrict pi = p[i];

          /* Value of path[i][k] before any possible update at column j == k.
             It is guaranteed to stay constant for all j < k, because
             path[i][k] is written only when j == k. */
          const DATA_TYPE pik_before = pi[k];

          /* Part 1: columns j in [0, k).
             Here path[i][k] is pik_before and does not change, so
             iterations are independent and access is purely row-major. */
#pragma GCC ivdep
          for (j = 0; j < k; j++)
            {
              const DATA_TYPE alt = pik_before + pk[j];
              if (alt < pi[j])
                pi[j] = alt;
            }

          /* Part 2: single column j == k.
             This is the *only* place where path[i][k] can change for this
             (i, k) pair.  We must use the original value (pik_before) on
             the right-hand side to exactly match the semantics of the
             original triple loop. */
          {
            const DATA_TYPE alt = pik_before + pk[k];
            if (alt < pi[k])
              pi[k] = alt;
          }

          /* Value of path[i][k] *after* the potential update at j == k.
             It remains constant for all j > k. */
          const DATA_TYPE pik_after = pi[k];

          /* Part 3: columns j in (k, _PB_N).
             Again, path[i][k] is invariant within this loop, and each
             iteration touches a distinct pi[j], so the compiler is free
             to vectorize. */
#pragma GCC ivdep
          for (j = k + 1; j < _PB_N; j++)
            {
              const DATA_TYPE alt = pik_after + pk[j];
              if (alt < pi[j])
                pi[j] = alt;
            }
        }
    }
#pragma endscop

}


int main(int argc, char** argv)
{
