/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_floyd_warshall [[gnu::flatten, gnu::noinline]] (int n,
			   DATA_TYPE POLYBENCH_2D(path,N,N,n,n))
{
  int i, j, k;

  /* Create a local restricted VLA pointer to improve alias analysis.
   * All accesses go through 'path_' inside this function.
   */
  DATA_TYPE (* restrict path_)[n] = path;

#pragma scop
  /* Standard Floyd–Warshall outer loop over intermediate vertex k. */
  for (k = 0; k < _PB_N; k++)
    {
      DATA_TYPE *row_k = path_[k];

      /* For each source vertex i, update the whole row path[i][*]
       * using vertex k as an intermediate.
       *
       * We split the original j-loop into three regions:
       *   j in [0, k)   : uses path[i][k] before it is updated
       *   j == k        : single iteration that updates path[i][k]
       *   j in (k, N)   : uses the (possibly) updated path[i][k]
       *
       * This preserves the exact sequential semantics of the original
       * triple loop for all possible data, but eliminates the apparent
       * loop-carried dependence on path[i][k] along j, which helps
       * the compiler vectorize the two larger j-ranges.
       */
      for (i = 0; i < _PB_N; i++)
        {
          DATA_TYPE *row_i = path_[i];

          /* Value of path[i][k] at the beginning of the j-loop.
           * In the original code, this is the value used for all
           * j < k and at j == k just before the update.
           */
          const DATA_TYPE path_ik_initial = row_i[k];

          /* 1) j in [0, k): path[i][k] has not been updated yet. */
          if (k > 0)
            {
              const DATA_TYPE path_ik_old = path_ik_initial;

              /* Each iteration writes a distinct row_i[j] and only reads
               * 'path_ik_old' and row_k[j]; there are no cross-iteration
               * dependencies, so it is safe to vectorize.
               */
#pragma GCC ivdep
              for (j = 0; j < k; j++)
                {
                  const DATA_TYPE via_k = path_ik_old + row_k[j];
                  const DATA_TYPE cur   = row_i[j];
                  row_i[j] = (cur < via_k) ? cur : via_k;
                }
            }

          /* 2) j == k: single iteration that updates path[i][k].
           *    Uses the value path[i][k] had at the start of the
           *    j-loop (path_ik_initial), exactly as in the original
           *    code.
           */
          {
            const DATA_TYPE diag_kk = row_k[k];
            const DATA_TYPE via_k   = path_ik_initial + diag_kk;
            const DATA_TYPE cur     = row_i[k];
            row_i[k] = (cur < via_k) ? cur : via_k;
          }

          /* 3) j in (k, N): here the original code uses the value of
           *    path[i][k] *after* the j == k update. We read it once
           *    into 'path_ik_new' and reuse it.
           */
          if (k + 1 < _PB_N)
            {
              const DATA_TYPE path_ik_new = row_i[k];

#pragma GCC ivdep
              for (j = k + 1; j < _PB_N; j++)
                {
                  const DATA_TYPE via_k = path_ik_new + row_k[j];
                  const DATA_TYPE cur   = row_i[j];
                  row_i[j] = (cur < via_k) ? cur : via_k;
                }
            }
        }
    }
#pragma endscop

}


