     compiler prove the absence of aliasing and enable better
     vectorization and code motion.
   - Cache row pointers (row_k, row_i) to reduce address computation
     and to iterate linearly in memory in the inner loop, improving
     spatial locality and making auto-vectorization easier.
   - Keep the original (k, i, j) loop ordering to strictly preserve
     the original computation semantics for all possible inputs.
*/
static void __attribute__((noinline))
kernel_floyd_warshall(int n,
                      DATA_TYPE POLYBENCH_2D(path,N,N,n,n))
{
  /* Create a restrict-qualified alias to the 2D array.
     Type: p is a pointer to an array of n DATA_TYPE elements. */
  DATA_TYPE (*restrict p)[n] = path;

  int k, i, j;
  const int N_ = _PB_N;

