  for (k = 0; k < N_; ++k)
  {
    /* Pointer to row k, reused for all i at this k.  This improves
       data locality for accesses to path[k][j]. */
    DATA_TYPE *restrict row_k = p[k];

    for (i = 0; i < N_; ++i)
